dir.commands:
select N'active$VoucherFilter$(this);' as message return
&XMLWhenFilterClosing;
select cast(0 as bit) as tag, a.*, case when loai_hd2 = '2' then _1thanh_ly else _2thanh_ly end as _thanh_ly, case when loai_hd2 = '2' then ngay_tl else _2ngay_tl end as _ngay_tl from vdmhdg a where (@nh_vv1 = '' or dbo.ff_ExactInlist(nh_vv1, @nh_vv1) = 1) and (@nh_hd1 = '' or dbo.ff_ExactInlist(nh_hd1, @nh_hd1) = 1) and (@nh_hd2 = '' or dbo.ff_ExactInlist(nh_hd2, @nh_hd2) = 1) and (@nh_hd3 = '' or dbo.ff_ExactInlist(nh_hd3, @nh_hd3) = 1) and (@ma_dvcs = '' or dbo.zcff_ExactInlist(list_dvcs, @ma_dvcs) = 1) and (@xtype = '*' or (@xtype = '1' and case when loai_hd2 = '2' then _1thanh_ly else _2thanh_ly end = 1) or (@xtype = '2' and case when loai_hd2 = '2' then _1thanh_ly else _2thanh_ly end = 0)) and loai_hd2 in ('2', '3') order by a.ma_hd

script.text:
			&OutlineEntry;

function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete);
	changeLookupReadonly(f, 'nh_vv1', false);
	changeLookupReadonly(f, 'nh_hd1', false);
	changeLookupReadonly(f, 'nh_hd2', false);
	changeLookupReadonly(f, 'nh_hd3', false);
	changeLookupReadonly(f, 'ma_dvcs', false);
}
function close$VoucherFilter$(f) {try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid; 
			break;
		default:
			break;
	}
}
